mapper.select:
SELECT DISTINCT o.id AS id, o.order_no AS orderNo, o.material_id AS materialId, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, m.unit_id AS unitId, o.scheme_version_id AS schemeVersionId, o.order_status AS orderStatus, o.batch_no AS batchNo, o.production_date AS productionDate, o.template_id AS templateId, o.remark AS remark, o.terminate_reason AS terminateReason, o.terminate_time AS terminateTime, o.create_time AS createTime, o.update_time AS updateTime, o.create_by AS createBy, o.update_by AS updateBy, /* 兼容“请验时间”语义 */ o.create_time AS requestTime FROM lm_inspection_order o INNER JOIN lm_task t ON t.inspection_order_id = o.id LEFT JOIN lm_inspect_material m ON m.id = o.material_id WHERE (o.order_status = 'CONFIRMED' or o.order_status='COMPLETED') AND (t.status = 'REVIEW_PASSED' or t.status='COMPLETED') AND t.execute_method = 'ELN'
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND o.material_id = #{materialId}
AND o.material_id IN
#{mid}
AND o.create_time >= #{inspectionRequestTimeStart}
AND o.create_time <= #{inspectionRequestTimeEnd}
ORDER BY o.create_time DESC, o.id DESC
